/**
 * Service worker (vanilla).
 *
 * Initial idea taken from:
 * https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Tutorials/CycleTracker/Service_workers
 * Can be used if doing a vanilla JS app.
 *
 * Usage:
 <!-- Test: response generated by service worker. -->
 <script async src="./js/worker-generated-script.js"></script>
 <script>
 // Check if service worker is supported.
 if ("serviceWorker" in navigator) {
 navigator.serviceWorker.register("./service-worker.js").then(
 (registration) => {
 console.log("Service worker registration successful:", registration);
 },
 (error) => {
 console.error(`Service worker registration failed: ${error}`);
 },
 );
 } else {
 console.error("Service workers are not supported.");
 }
 </script>
 */

const APP_VERSION = "0.0.0";
const APP_CACHE_NAME = `hrdr-${APP_VERSION}`;
const APP_STATIC_ASSETS = [
    "/index.html",
    "/css/app.css",
    "/img/icons/192.png",
    "/img/icons/512.png",
    "/img/icons/apple-touch-icon.png",
    "/img/icons/favicon.ico",
];

/**
 * Saving the cache on PWA installation
 * https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Tutorials/CycleTracker/Service_workers#saving_the_cache_on_pwa_installation
 * Install event only triggers once.
 */
self.addEventListener("install", (event) => {
    console.log("[Service Worker] install event");

    event.waitUntil(
        (async () => {
            const cache = await caches.open(APP_CACHE_NAME);
            console.log("[Service Worker] Caching all.");
            // Note: with addAll, if one fails, all are discarded.
            return cache.addAll(APP_STATIC_ASSETS);
        })()
    );
});

/**
 * Updating the PWA and deleting old caches
 * https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Tutorials/CycleTracker/Service_workers#updating_the_pwa_and_deleting_old_caches
 */
self.addEventListener("activate", (event) => {
    console.log("[Service Worker] activate event");

    event.waitUntil(
        (async () => {
            const names = await caches.keys();
            await Promise.all(
                names.map((name) => {
                    if (name !== APP_CACHE_NAME) {
                        return caches.delete(name);
                    }
                })
            );
            // Seems this (from Firefox) si discouraged (by Google):
            await clients.claim();
        })()
    );
});

/**
 * Intercept requests
 *
 * https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Tutorials/CycleTracker/Service_workers#the_fetch_event
 */
self.addEventListener("fetch", (event) => {

    console.log(`[Service Worker] fetch event: ${event.request.url}`);

    /*
    // Initial approach, from fist tutorial

    // when seeking an HTML page
    if (event.request.mode === "navigate") {
        // Return to the index.html page
        event.respondWith(caches.match("/index.html"));
        return;
    }

    // For every other request type
    event.respondWith(
        (async () => {
            const cache = await caches.open(APP_CACHE_NAME);
            const cachedResponse = await cache.match(event.request.url);
            if (cachedResponse) {
                // Return the cached response if it's available.
                return cachedResponse;
            } else {
                // Respond with a HTTP 404 response status.
                return new Response(null, { status: 404 });
            }
        })()
    );
     */

    // Parse the URL. https://medium.com/dev-channel/service-worker-caching-strategies-based-on-request-types-57411dd7652c
    const requestURL = new URL(event.request.url);

    /* Test: response generated by service worker. */
    if (requestURL.pathname === '/js/worker-generated-script.js') {
        event.respondWith(
            (async () => {
                const responseOptions = {
                    status: 200,
                    headers: {
                        'Content-type': 'text/javascript',
                    },
                };
                console.log("[Service Worker] returning dynamic resource.");
                return new Response("alert('hello')", responseOptions);
            })()
        );
        return;
    }

    // Different approach, from the other tutorial
    // https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Tutorials/js13kGames/App_structure
    event.respondWith(
        (async () => {
            const cache = await caches.open(APP_CACHE_NAME);

            const cachedResponse = await cache.match(event.request);
            console.log(`[Service Worker] Fetching resource: ${event.request.url}`);
            if (cachedResponse) {
                console.log("[Service Worker] returning cached resource.");
                return cachedResponse;
            }

            const serverResponse = await fetch(event.request);
            console.log(`[Service Worker] Caching new resource: ${event.request.url}`);
            cache.put(event.request, serverResponse.clone());
            console.log("[Service Worker] returning network resource.");
            return serverResponse;
        })()
    );
});